// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.SplittableRandom;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbDeferredValueLookupsTest {

	@TempDir
	Path directory;

	private final ExecutorService executor = Executors.newFixedThreadPool(2);

	@AfterEach
	void shutDown() {
		executor.shutdownNow();
	}

	@Test
	void recordsComeBackInLmdbKeyOrderWithTheirIds() throws Exception {
		List<byte[]> keys = new ArrayList<>();
		// Prefix relations, embedded and trailing zero bytes, high bytes, and every length from 1 to 16.
		keys.add(new byte[] { 0 });
		keys.add(new byte[] { 0, 0 });
		keys.add(new byte[] { 1, 0, 0 });
		keys.add(new byte[] { 1, 0 });
		keys.add(new byte[] { 1 });
		keys.add(new byte[] { (byte) 0xFF });
		keys.add(new byte[] { (byte) 0x80, 1 });
		SplittableRandom random = new SplittableRandom(7);
		for (int i = 0; i < 2_000; i++) {
			byte[] key = new byte[1 + random.nextInt(LmdbDeferredValueLookups.MAX_KEY_BYTES)];
			for (int b = 0; b < key.length; b++) {
				key[b] = (byte) random.nextInt(4) == 0 ? 0 : (byte) random.nextInt(256);
			}
			if (keys.stream().noneMatch(existing -> Arrays.equals(existing, key))) {
				keys.add(key);
			}
		}
		try (LmdbDeferredValueLookups lookups = new LmdbDeferredValueLookups(directory, 97, 3, executor)) {
			for (int i = 0; i < keys.size(); i++) {
				lookups.add(keys.get(i), keys.get(i).length, 1_000L + i);
				if (i % 50 == 49) {
					lookups.commit();
				}
			}
			lookups.commit();
			List<byte[]> expected = new ArrayList<>(keys);
			expected.sort(Arrays::compareUnsigned);

			List<byte[]> merged = new ArrayList<>();
			try (LmdbDeferredValueLookups.Source source = lookups.complete()) {
				ByteBuffer key = ByteBuffer.allocate(LmdbDeferredValueLookups.MAX_KEY_BYTES);
				long id;
				while ((id = source.next(key)) >= 0) {
					byte[] bytes = new byte[key.remaining()];
					key.get(bytes);
					assertThat(id).as("the ID recorded for this key").isEqualTo(1_000L + indexOf(keys, bytes));
					merged.add(bytes);
				}
			}
			assertThat(merged).hasSize(expected.size());
			for (int i = 0; i < expected.size(); i++) {
				assertThat(merged.get(i)).as("record %d", i).isEqualTo(expected.get(i));
			}
		}
	}

	@Test
	void rolledBackRecordsDisappearAndKeysRecordedTwiceAreRejected() throws Exception {
		try (LmdbDeferredValueLookups lookups = new LmdbDeferredValueLookups(directory, 16, 1, executor)) {
			lookups.add(new byte[] { 3, 1 }, 2, 1);
			lookups.commit();
			lookups.add(new byte[] { 3, 2 }, 2, 2);
			lookups.rollback();
			assertThat(lookups.committedRecords()).isEqualTo(1);
			try (LmdbDeferredValueLookups.Source source = lookups.complete()) {
				ByteBuffer key = ByteBuffer.allocate(LmdbDeferredValueLookups.MAX_KEY_BYTES);
				assertThat(source.next(key)).isEqualTo(1);
				assertThat(source.next(key)).isEqualTo(-1);
			}
		}
		try (LmdbDeferredValueLookups lookups = new LmdbDeferredValueLookups(directory, 16, 1, executor)) {
			lookups.add(new byte[] { 4, 4 }, 2, 1);
			lookups.add(new byte[] { 4, 4 }, 2, 2);
			lookups.commit();
			try (LmdbDeferredValueLookups.Source source = lookups.complete()) {
				ByteBuffer key = ByteBuffer.allocate(LmdbDeferredValueLookups.MAX_KEY_BYTES);
				source.next(key);
				assertThatThrownBy(() -> source.next(key)).isInstanceOf(IOException.class);
			}
		}
		try (LmdbDeferredValueLookups lookups = new LmdbDeferredValueLookups(directory, 16, 1, executor)) {
			assertThatThrownBy(() -> lookups.add(new byte[17], 17, 1)).isInstanceOf(IllegalArgumentException.class);
		}
	}

	private static int indexOf(List<byte[]> keys, byte[] key) {
		for (int i = 0; i < keys.size(); i++) {
			if (Arrays.equals(keys.get(i), key)) {
				return i;
			}
		}
		return -1;
	}
}
